class Solution:
    def compareSums(self, nums: List[int]) -> int:
        p = 0
        while p + 1 < len(nums) and nums[p + 1] > nums[p]:
            p += 1
        asc = sum(nums[:p + 1])
        desc = sum(nums[p:])
        return 0 if asc > desc else 1 if desc > asc else -1

