class Solution {
public:
    int compareSums(vector<int>& nums) {
        int p = 0;
        while (p + 1 < (int)nums.size() && nums[p + 1] > nums[p]) p++;
        long long asc = accumulate(nums.begin(), nums.begin() + p + 1, 0LL);
        long long desc = accumulate(nums.begin() + p, nums.end(), 0LL);
        return asc > desc ? 0 : (desc > asc ? 1 : -1);
    }
};

