class Solution {
    public int compareSums(int[] nums) {
        int p = 0;
        while (p + 1 < nums.length && nums[p + 1] > nums[p]) p++;
        long asc = 0, desc = 0;
        for (int i = 0; i <= p; i++) asc += nums[i];
        for (int i = p; i < nums.length; i++) desc += nums[i];
        return asc > desc ? 0 : (desc > asc ? 1 : -1);
    }
}

