        lo, hi = 0, len(nums) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if nums[mid] < nums[mid + 1]:
                lo = mid + 1
            else:
                hi = mid
        asc = sum(nums[:lo + 1])
        desc = sum(nums[lo:])
        return 0 if asc > desc else 1 if desc > asc else -1

