        int lo = 0, hi = nums.size() - 1;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (nums[mid] < nums[mid + 1]) lo = mid + 1;
            else hi = mid;
        }
        long long asc = accumulate(nums.begin(), nums.begin() + lo + 1, 0LL);
        long long desc = accumulate(nums.begin() + lo, nums.end(), 0LL);
        return asc > desc ? 0 : (desc > asc ? 1 : -1);
    }
};

